'use strict';
window.renderBundlePayment=async(parent,proof,en=false,preferred='',expectedTotal=null)=>{
 const el=(tag,text)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n;},tr=(a,b)=>en?b:a,box=el('section'),status=el('p'),payment=el('div'),refresh=el('button',tr('Kiểm tra trạng thái thanh toán','Check payment status'));box.append(el('h2',tr('Thanh toán đơn hàng','Order payment')),status,payment,refresh);parent.append(box);refresh.type='button';const frozen={code:proof.code,accessKey:proof.accessKey};let busy=false;
 async function load(){if(busy||!box.isConnected)return;busy=true;refresh.disabled=true;status.textContent=tr('Đang kiểm tra thanh toán…','Checking payment status…');payment.replaceChildren();try{const response=await fetch('/api/v1/payments/bundles/lookup',{method:'POST',credentials:'omit',cache:'no-store',headers:{'Content-Type':'application/json','X-JinMemo-Request':'1'},body:JSON.stringify(frozen)}),data=await response.json();if(!box.isConnected)return;if(!response.ok)throw Error((typeof guestError==='function'?guestError(data?.message):data?.message)||tr('Không tra cứu được thanh toán.','Unable to check payment.'));if(!data||typeof data!=='object'||data.code!==frozen.code||!Number.isSafeInteger(data.total)||data.total<1||data.total>15000000000||expectedTotal!==null&&data.total!==expectedTotal||!['PAID','UNPAID'].includes(data.paymentStatus))throw Error(tr('Kết quả thanh toán chưa xác minh được.','Payment status could not be verified.'));if(data.paymentStatus==='PAID'){status.textContent=tr('Đã ghi nhận thanh toán cho toàn bộ đơn. Lịch xe và giao vé vẫn được xử lý theo xác nhận riêng.','Payment is recorded for the full order. Transfer scheduling and ticket delivery follow their separate confirmations.');return;}status.textContent=tr('Chưa ghi nhận thanh toán.','Payment has not been recorded.');if(data.manual)ticketPaymentSummary(payment,data.manual,en);const selected=data.method||preferred;if(window.jinmemoPaymentMethods?.isOnline(selected))payment.append(el('p',tr('Cổng đã chọn: ','Selected gateway: ')+window.jinmemoPaymentMethods.label(selected,en)));await renderOnlinePayment(payment,frozen,en,null,{preferredProvider:window.jinmemoPaymentMethods?.isOnline(selected)?selected:'',expectedTotal:data.total});}catch(error){if(box.isConnected)status.textContent=error.message;}finally{busy=false;refresh.disabled=false;}}
 refresh.onclick=load;await load();
};
